import java.util.*;
import org.simplepoint.platform.composition.*;
import org.simplepoint.platform.dictionary.*;
import org.simplepoint.platform.dictionary.registration.*;
import org.simplepoint.remoting.RemoteContract;
import org.springframework.transaction.annotation.Transactional;

public class VerifyDictionaryRegistrationArtifacts {
  public static void main(String[] args) throws Exception {
    var loader = VerifyDictionaryRegistrationArtifacts.class.getClassLoader();
    var catalog = ModuleCatalog.discover(loader);
    var plan = catalog.plan(List.of("identity", "oidc", "notification"));
    var capability = "security.dictionary-registration:1";
    if (!"identity".equals(plan.capabilityOwners().get(capability)))
      throw new AssertionError("Dictionary authority not owned by identity");
    for (var module : plan.modules()) {
      if (Set.of("oidc", "notification").contains(module.id())
          && (!module.initializers().contains(DictionaryModuleInitializer.class)
              || module.consumes().get(capability) != DictionaryRegistrationService.class))
        throw new AssertionError("Initializer or derived consumer missing: " + module.id());
    }
    var remote = catalog.plan(List.of("oidc", "notification"));
    if (remote.remoteCapabilities().get(capability) != DictionaryRegistrationService.class)
      throw new AssertionError("Separated deployment missing dictionary dependency");
    var contract = DictionaryRegistrationService.class.getAnnotation(RemoteContract.class);
    var methods = DictionaryRegistrationService.class.getDeclaredMethods();
    if (!contract.isolateLocalCalls() || methods.length != 1 || !methods[0].getName().equals("apply"))
      throw new AssertionError("Public contract leaked management or lost isolation");
    for (String name : List.of("DictionaryRegistrationApplication", "DictionaryRegistrationStore")) {
      var type = Class.forName("org.simplepoint.plugin.rbac.tenant.service.initialize." + name);
      var entry = Arrays.stream(type.getDeclaredMethods())
          .filter(m -> m.getName().equals(name.endsWith("Store") ? "install" : "apply")).findFirst().orElseThrow();
      if (entry.getAnnotation(Transactional.class) == null)
        throw new AssertionError("Missing authoritative transaction");
    }
    for (String name : List.of(
        "org.simplepoint.platform.dictionary.registration.DictionaryRegistrationService",
        "org.simplepoint.platform.dictionary.registration.DictionaryModuleInitializer",
        "org.simplepoint.plugin.rbac.tenant.service.initialize.DictionaryRegistrationApplication",
        "org.simplepoint.plugin.rbac.tenant.service.initialize.DictionaryRegistrationStore",
        "org.simplepoint.plugin.rbac.tenant.service.initialize.DictionaryRegistrationProvider")) {
      if (Collections.list(loader.getResources(name.replace('.', '/') + ".class")).size() != 1)
        throw new AssertionError("Missing or duplicated artifact: " + name);
    }
    var migration = "META-INF/simplepoint/modules/identity/db/postgresql/V7__dictionary_registration_authority.sql";
    if (Collections.list(loader.getResources(migration)).size() != 1)
      throw new AssertionError("Missing or duplicate migration");
    try (var stream = loader.getResourceAsStream("META-INF/simplepoint/modules/identity/db/manifest.properties")) {
      var manifest = new Properties(); manifest.load(stream);
      if (!manifest.getProperty("migrations").contains("V7__dictionary_registration_authority.sql"))
        throw new AssertionError("V7 not declared");
      for (String suffix : List.of("operations", "approvals", "owners")) {
        if (!manifest.getProperty("tables").contains("simpoint_dictionary_registration_" + suffix))
          throw new AssertionError("Authority table not declared: " + suffix);
      }
    }
    System.out.println("Installed Common distribution verified: identity-owned narrow isolated dictionary RPC, OIDC/notification initializers and derived remote requirements, transactional installation/application, unique provider artifacts and V7 migration/three tables.");
  }
}
